const guideDetails={
 '800+':{basis:'Ustawa o pomocy państwa w wychowywaniu dzieci',dates:'Nowy okres trwa od czerwca do maja; nabór zaczyna się 1 lutego. Złożenie do 30 kwietnia ma znaczenie dla ciągłości wypłat, a do 30 czerwca — dla ustalenia prawa od czerwca. Dla noworodka 3 miesiące od narodzin pozwalają ustalić prawo od urodzenia.',checks:'Wiek, zamieszkiwanie i opieka nad dzieckiem, status pobytu i szczególne zasady dla cudzoziemców, opieka naprzemienna oraz koordynacja zagraniczna.',documents:'Właściwy elektroniczny wniosek w eZUS / mZUS lub innym dopuszczonym kanale; dokument opieki, pobytu albo orzeczenie sądu, jeśli wymagany.'},
 'Aktywni rodzice w pracy':{basis:'Ustawa z 15 maja 2024 r. „Aktywny rodzic”',dates:'Co do zasady miesiące wieku 12–35; nie przenosimy tego okresu na świadczenie żłobkowe.',checks:'Aktywność i podstawy składek obojga opiekunów albo warunki samotnego wychowywania. Właściwe orzeczenie może wpływać na wysokość. Jedno świadczenie programu na dziecko w danym miesiącu.',documents:'Elektroniczny wniosek do ZUS; dane drugiej osoby wspólnie wychowującej dziecko, dokument pobytu / opieki i orzeczenie, gdy wymagane.'},
 'Aktywnie w żłobku':{basis:'Ustawa z 15 maja 2024 r. „Aktywny rodzic”',dates:'Zależy od korzystania z uprawnionej placówki; sprawdź aktualny termin wniosku i zgłoszenia dziecka.',checks:'Wpis placówki do właściwego rejestru, faktyczna opłata bez wyżywienia, limit opłat i inne świadczenia na to dziecko. Nie jest przelewem do dowolnego opiekuna.',documents:'Elektroniczny wniosek ZUS i zgodne dane dziecka w rejestrze placówki; ZUS może zażądać dodatkowych dokumentów.'},
 'Aktywnie w domu':{basis:'Ustawa z 15 maja 2024 r. „Aktywny rodzic”',dates:'Co do zasady miesiące wieku 12–35.',checks:'Opieka nad dzieckiem, status uprawnionej osoby i pobytu, inne świadczenia programu oraz przejściowe rozliczenie wcześniejszego RKO.',documents:'Elektroniczny wniosek do ZUS; dokumenty właściwe dla opieki i pobytu, jeżeli potrzebne.'},
 'Świadczenie rodzicielskie':{basis:'Art. 17c ustawy o świadczeniach rodzinnych',dates:'Wniosek w ciągu 3 miesięcy od właściwego zdarzenia ma znaczenie dla wypłaty od początku. Późniejszy wniosek nie oznacza automatycznie utraty całego pozostałego okresu.',checks:'Brak wyłączającego macierzyńskiego / uposażenia, rzeczywista opieka, liczba dzieci, adopcja / piecza i szczególne przejęcie przez ojca. Hospitalizacja może przedłużać okres na odrębnych zasadach.',documents:'Wniosek do właściwej gminy / organu świadczeń rodzinnych, dane dziecka i dokumenty przyjęcia; dokument szpitala przy wydłużeniu.'},
 'Becikowe':{basis:'Art. 15b ustawy o świadczeniach rodzinnych',dates:'Przy urodzeniu zasadniczo 12 miesięcy od narodzin. Przy przyjęciu dziecka sprawdź odrębne kotwice i granicę wieku.',checks:'Kryterium dochodowe i dokumentacja opieki medycznej od wymaganego momentu ciąży; wyjątki dla osób przyjmujących dziecko na wychowanie.',documents:'Wniosek gminny, dane dochodowe i zaświadczenie medyczne, jeżeli wymagane; dokument przyjęcia dziecka, gdy dotyczy.'},
 'Jednorazowe świadczenie „Za życiem”':{basis:'Art. 4 ustawy o wsparciu kobiet w ciąży i rodzin „Za życiem”',dates:'12 miesięcy od narodzin, a dla właściwego przyjęcia pod opiekę / przysposobienia — od tego zdarzenia, nie później niż do 18. urodzin. Nie jest to termin wniosku o wydłużony rodzicielski ZUS.',checks:'Ustawowe zaświadczenie o ciężkim i nieodwracalnym upośledzeniu albo nieuleczalnej chorobie zagrażającej życiu; inne warunki tej procedury. Samo orzeczenie o niepełnosprawności nie zastępuje zaświadczenia.',documents:'Wniosek do organu świadczeń rodzinnych, właściwe zaświadczenie i wymagane potwierdzenie opieki medycznej; dla biologicznych rodziców co do zasady od najpóźniej 10. tygodnia ciąży do porodu.'},
 'Świadczenie pielęgnacyjne':{basis:'Art. 17 ustawy o świadczeniach rodzinnych',dates:'Istotna jest data wniosku, okres orzeczenia oraz wybór właściwego reżimu przepisów; nie zakładamy prawa dożywotniego.',checks:'Wiek osoby wymagającej opieki, status opiekuna i konkretne wskazania orzeczenia. Uprawnienia nabyte według wcześniejszych zasad wymagają oddzielnej oceny.',documents:'Wniosek organu świadczeń rodzinnych, orzeczenie z wymaganymi wskazaniami i dokument relacji / opieki.'},
 'Zasiłek pielęgnacyjny':{basis:'Art. 16 ustawy o świadczeniach rodzinnych',dates:'Znaczenie ma okres ważności orzeczenia i data wniosku.',checks:'Właściwy rodzaj niepełnosprawności, wiek i wyłączenia związane z innymi uprawnieniami. Nie jest wynagrodzeniem opiekuna.',documents:'Wniosek właściwego organu i odpowiednie orzeczenie.'},
 'Wsparcie pieczy zastępczej':{basis:'Ustawa o wspieraniu rodziny i systemie pieczy zastępczej',dates:'Początek i koniec faktycznej pieczy oraz orzeczenia / umowy mają znaczenie dla okresu pomocy.',checks:'Rodzina spokrewniona, niezawodowa, zawodowa lub rodzinny dom dziecka; potrzeby dziecka i inne wypłaty.',documents:'Dokument umieszczenia, umowa i wniosek do PCPR / organizatora właściwy dla danego rodzaju wsparcia.'},
 'Urlop wychowawczy':{basis:'Art. 186 i następne Kodeksu pracy',dates:'Wniosek pracownika co najmniej 21 dni przed planowanym rozpoczęciem; sprawdź granice wieku oraz odrębny wymiar przy niepełnosprawności.',checks:'Co najmniej 6 miesięcy zatrudnienia łącznie, wykorzystanie i części obojga rodziców oraz nieprzenoszalny miesiąc i ustawowe wyjątki.',documents:'Wniosek do pracodawcy, historia wykorzystania, oświadczenia drugiego rodzica, orzeczenie i dokument wyjątku, gdy potrzebne.'},
 'Zwolnienie na opiekę nad dzieckiem':{basis:'Art. 188 Kodeksu pracy',dates:'Roczny limit 2 dni albo 16 godzin przy dziecku przed 14. urodzinami; sposób korzystania wybiera pierwszy wniosek w roku.',checks:'Uprawnienie pracownicze i wykorzystanie przez drugiego rodzica; w wariancie godzinowym niepełny etat wpływa na limit.',documents:'Wniosek / oświadczenie do pracodawcy o sposobie korzystania i wykorzystaniu przez drugiego rodzica.'},
 'Urlop opiekuńczy':{basis:'Art. 173¹ i następne Kodeksu pracy',dates:'5 dni w roku kalendarzowym, wniosek co najmniej 1 dzień przed rozpoczęciem.',checks:'Poważne względy medyczne oraz ustawowy członek rodziny lub wspólne gospodarstwo. Urlop jest bezpłatny i nie zastępuje opiekuńczego ZUS.',documents:'Wniosek do pracodawcy ze wskazaniem osoby, przyczyny opieki oraz wymaganej relacji / wspólnego adresu.'},
 'Siła wyższa':{basis:'Art. 148¹ Kodeksu pracy',dates:'2 dni albo 16 godzin w roku; wniosek najpóźniej w dniu korzystania.',checks:'Pilna sprawa rodzinna spowodowana chorobą / wypadkiem i niezbędna natychmiastowa obecność. Przysługuje połowa wynagrodzenia; godzinowy limit niepełnego etatu jest proporcjonalny.',documents:'Wniosek do pracodawcy i wybór dni lub godzin w pierwszym wniosku w roku.'},
 'Karmienie i bezpieczna praca':{basis:'Art. 176, 179 i 187 Kodeksu pracy',dates:'Znaczenie ma rzeczywisty okres ciąży / karmienia i dobowy wymiar pracy.',checks:'Liczba karmionych dzieci, długość dnia pracy i rodzaj czynników szkodliwych; dostosowanie obowiązków przez pracodawcę.',documents:'Informacja / wniosek do pracodawcy; potwierdzenie ciąży i inne dokumenty wymagane w odpowiedniej procedurze.'},
 'Ochrona zatrudnienia i powrót':{basis:'Art. 177, 183², 186⁴ i następne Kodeksu pracy',dates:'Rozróżnij datę wniosku, początek urlopu, powrót i koniec umowy.',checks:'Rodzaj umowy, chroniony okres, ustawowe wyjątki i właściwe warunki powrotu / obniżenia etatu. Ochrona nie oznacza przedłużenia każdej umowy.',documents:'Wniosek / dokument powrotu do pracodawcy i historia umowy; przy sporze pomoc PIP lub właściwa droga sądowa.'}
};
for(const r of RIGHTS_GUIDE)Object.assign(r,guideDetails[r.title]||{}, {assessment:'Informacja proceduralna — indywidualne prawo wymaga sprawdzenia warunków przez właściwy organ.'});
export function rightsGuideHtml(){return `<section class="case-card rights-guide"><h2>Inne świadczenia i prawa pracownicze</h2><p>Nie wszystkie sprawy należą do ZUS. Poniższe informacje kierują do właściwej instytucji; nie stanowią automatycznej oceny prawa ani wyliczenia.</p><div class="case-card-grid">${RIGHTS_GUIDE.map(r=>`<details class="term-explanations"><summary>${r.title}</summary><p><strong>${r.institution}</strong></p><p>${r.description}</p><h3>Co ma znaczenie?</h3><p>${r.checks}</p><h3>Kiedy działać?</h3><p>${r.dates}</p><h3>Co przygotować i gdzie złożyć?</h3><p>${r.documents}</p><p>${r.assessment}</p><p>Podstawa: ${r.basis}.</p><a href="${r.url}" target="_blank" rel="noopener noreferrer">Oficjalne informacje i warunki</a></details>`).join('')}</div></section>`;}
